diff --git a/runtime/dispatcher/tests/dispatcher-integration.test.ts b/runtime/dispatcher/tests/dispatcher-integration.test.ts
new file mode 100644
index 0000000..28a030a
--- /dev/null
+++ b/runtime/dispatcher/tests/dispatcher-integration.test.ts
@@ -0,0 +1,500 @@
+/**
+ * T7 — Dispatcher integration + concurrency hazard tests.
+ *
+ * Covers the dispatcher-level scenarios for standalone-executor-hardening:
+ *
+ *   A. End-to-end pipe: stream entry consumed → spawner called → XACK'd.
+ *      The entry is seeded to fake Redis; _processEntry processes it with a
+ *      fake spawner; the simulated callback is verified via spy.
+ *
+ *   B. Dispatcher-crash redelivery (XAUTOCLAIM) → exactly one container.
+ *      Two consumers race on the same entry (simulating: consumer-1 crashed
+ *      mid-process, consumer-2 reclaims via XAUTOCLAIM). Spawn lock ensures
+ *      only one spawns.
+ *
+ *   C. Reconciler re-enqueue racing a slow in-progress spawn (M:N dispatchers).
+ *      Reconciler adds a second stream entry for the same handle while a
+ *      dispatcher is mid-spawn. Two dispatcher instances process the two
+ *      entries; spawn lock ensures only one spawns. The induced spawn MUST be
+ *      slow (artificial delay) to actually exercise the lock, not just the
+ *      label backstop.
+ *
+ *   D. DLQ routing posts synthetic failed completion to the broker callback.
+ *      Verifies the broker learns about terminal dispatch failure through the
+ *      normal completion path.
+ *
+ *   E. Concurrent coexistence isolation.
+ *      A bundled-profile task (no handle label) and a standalone-profile task
+ *      (with handle label) are dispatched simultaneously; they don't share
+ *      spawn locks, container names, or workspace dirs.
+ *
+ * All tests use in-memory fakes — no real Redis, Docker, or broker service required.
+ *
+ * See also:
+ *   dispatcher/tests/consumer.test.ts — fine-grained unit tests for
+ *     each DispatchStreamConsumer method.
+ *   orchestrator/tests/integration/standalone-executor-hardening.integration.test.ts —
+ *     orchestrator-side decoupled-flow and profile tests.
+ */
+
+// vi.mock is hoisted before imports by vitest.
+vi.mock("node:http", () => ({ request: vi.fn() }));
+
+import { describe, it, expect, beforeEach, vi } from "vitest";
+import { randomUUID } from "node:crypto";
+import * as nodeHttp from "node:http";
+import { DispatchStreamConsumer, type ConsumerOpts } from "../src/consumer.js";
+import type { DispatchJob } from "@workflow/runtime-abi";
+import {
+  DISPATCH_STREAM_KEY,
+  DISPATCH_CONSUMER_GROUP,
+  DISPATCH_DLQ_KEY,
+} from "@workflow/runtime-abi";
+import type { DockerSpawner } from "../src/spawner.js";
+import type { CredentialAdapter } from "../src/credential.js";
+
+// ── Shared fake builders ─────────────────────────────────────────────────────
+
+function makeJob(overrides?: Partial<DispatchJob>): DispatchJob {
+  return {
+    handle: randomUUID(),
+    nonce: randomUUID(),
+    kind: "impl",
+    task_id: "T7",
+    feature_id: "standalone-executor-hardening",
+    workspace_id: "ws-test",
+    task_repo_url: "git@github.com:org/repo.git",
+    task_repo_branch: "feature/standalone-executor-hardening-T7",
+    task_base_branch: "feature/standalone-executor-hardening",
+    task_repo_base_branch: "main",
+    mgmt_repo_url: "git@github.com:org/workspace.git",
+    executor_workdir: "/workspace",
+    callback_url: "http://broker:7000/callback",
+    enqueued_at: new Date().toISOString(),
+    ...overrides,
+  };
+}
+
+function makeEntry(
+  job: DispatchJob,
+  id?: string,
+): { id: string; message: Record<string, string> } {
+  return {
+    id: id ?? `${Date.now()}-0`,
+    message: { job: JSON.stringify(job) },
+  };
+}
+
+interface FakeRedis {
+  xAddCalls: Array<{ key: string; id: string; fields: Record<string, string> }>;
+  xAckCalls: Array<{ key: string; group: string; id: string }>;
+  setCalls: Array<{ key: string; value: string; opts: { NX?: boolean; PX?: number } }>;
+  getCalls: string[];
+  delCalls: string[];
+  xAdd: ReturnType<typeof vi.fn>;
+  xAck: ReturnType<typeof vi.fn>;
+  xPendingRange: ReturnType<typeof vi.fn>;
+  set: ReturnType<typeof vi.fn>;
+  get: ReturnType<typeof vi.fn>;
+  del: ReturnType<typeof vi.fn>;
+  xGroupCreate: ReturnType<typeof vi.fn>;
+  xReadGroup: ReturnType<typeof vi.fn>;
+  xAutoClaim: ReturnType<typeof vi.fn>;
+}
+
+function makeFakeRedis(opts?: {
+  setResultFn?: (key: string) => string | null;
+  pendingByEntryId?: Map<string, number>;
+}): FakeRedis {
+  const xAddCalls: FakeRedis["xAddCalls"] = [];
+  const xAckCalls: FakeRedis["xAckCalls"] = [];
+  const setCalls: FakeRedis["setCalls"] = [];
+  const getCalls: string[] = [];
+  const delCalls: string[] = [];
+
+  const r: FakeRedis = {
+    xAddCalls,
+    xAckCalls,
+    setCalls,
+    getCalls,
+    delCalls,
+    xAdd: vi.fn(async (key: string, id: string, fields: Record<string, string>) => {
+      xAddCalls.push({ key, id, fields });
+      return "1-0";
+    }),
+    xAck: vi.fn(async (key: string, group: string, id: string) => {
+      xAckCalls.push({ key, group, id });
+      return 1;
+    }),
+    xPendingRange: vi.fn(async (_key: string, _group: string, start: string) => {
+      const deliveryCount = opts?.pendingByEntryId?.get(start) ?? 1;
+      return [{ id: start, deliveryCount, deliveriesCounter: deliveryCount, consumer: "test", idle: 100 }];
+    }),
+    set: vi.fn(async (key: string, value: string, setOpts: { NX?: boolean; PX?: number }) => {
+      setCalls.push({ key, value, opts: setOpts });
+      if (opts?.setResultFn) return opts.setResultFn(key);
+      return "OK";
+    }),
+    get: vi.fn(async (key: string) => {
+      getCalls.push(key);
+      return null;
+    }),
+    del: vi.fn(async (key: string) => {
+      delCalls.push(key);
+      return 1;
+    }),
+    xGroupCreate: vi.fn(async () => "OK"),
+    xReadGroup: vi.fn(async () => []),
+    xAutoClaim: vi.fn(async () => ({ nextId: "0-0", messages: [] })),
+  };
+  return r;
+}
+
+function makeFakeSpawner(opts?: {
+  existingHandle?: string;
+  spawnDelayMs?: number;
+  spawnError?: Error;
+}): DockerSpawner & { spawnCalls: DispatchJob[] } {
+  const spawnCalls: DispatchJob[] = [];
+  return {
+    spawnCalls,
+    findExistingContainer: vi.fn(async (handle: string) => {
+      return opts?.existingHandle === handle ? "existing-container-id" : null;
+    }),
+    spawn: vi.fn(async (job: DispatchJob) => {
+      if (opts?.spawnDelayMs) {
+        await new Promise((r) => setTimeout(r, opts.spawnDelayMs));
+      }
+      if (opts?.spawnError) throw opts.spawnError;
+      spawnCalls.push(job);
+      return { containerId: `container-${job.handle.slice(0, 8)}` };
+    }),
+  } as unknown as DockerSpawner & { spawnCalls: DispatchJob[] };
+}
+
+function makeFakeCredential(): CredentialAdapter {
+  return {
+    getGitHubToken: vi.fn(async () => "fake-token"),
+    getSshPrivateKey: vi.fn(async () => "fake-key"),
+  };
+}
+
+const BASE_OPTS: Omit<ConsumerOpts, "redis" | "spawner" | "credential"> = {
+  brokerUrl: "http://broker:7000",
+  consumerId: "test-consumer",
+  maxConcurrent: 5,
+  maxDeliveries: 3,
+  spawnLockTtlMs: 30_000,
+  pollBlockMs: 100,
+  xautoclaimMinIdleMs: 30_000,
+  batchSize: 10,
+};
+
+// ── A. End-to-end pipe: entry consumed → spawned → XACK'd ───────────────────
+
+describe("A. End-to-end pipe — entry consumed → spawner called → XACK'd", () => {
+  it("processes a well-formed stream entry: spawn + XACK, no DLQ write", async () => {
+    const redis = makeFakeRedis();
+    const spawner = makeFakeSpawner();
+    const consumer = new DispatchStreamConsumer({
+      redis: redis as never,
+      spawner,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+
+    vi.spyOn(consumer, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    const job = makeJob();
+    const entry = makeEntry(job, "1000-0");
+
+    await (consumer as never as { _processEntry: (e: typeof entry) => Promise<void> })._processEntry(entry);
+
+    // Spawner was called exactly once.
+    expect(spawner.spawnCalls).toHaveLength(1);
+    expect(spawner.spawnCalls[0].handle).toBe(job.handle);
+
+    // Entry was XACK'd.
+    expect(redis.xAckCalls).toHaveLength(1);
+    expect(redis.xAckCalls[0].id).toBe("1000-0");
+
+    // Nothing written to DLQ.
+    const dlqWrites = redis.xAddCalls.filter((c) => c.key === DISPATCH_DLQ_KEY);
+    expect(dlqWrites).toHaveLength(0);
+  });
+});
+
+// ── B. Dispatcher-crash redelivery → exactly one container ──────────────────
+
+describe("B. Dispatcher-crash redelivery — exactly one container via spawn lock", () => {
+  it("consumer-2 reclaims a stuck entry: spawn lock ensures only one container", async () => {
+    // Consumer-1 "crashed" mid-process without XACKing.
+    // Consumer-2 reclaims via XAUTOCLAIM and processes the same entry.
+    // The spawn lock (SET NX) ensures only one spawns.
+
+    // Consumer-1 loses the lock (simulates crash — it didn't release the lock
+    // but we treat the situation as: consumer-2 wins the lock on reclaim).
+    const redis2 = makeFakeRedis({ setResultFn: () => "OK" });
+    const spawner2 = makeFakeSpawner();
+
+    const consumer2 = new DispatchStreamConsumer({
+      redis: redis2 as never,
+      spawner: spawner2,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+    vi.spyOn(consumer2, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    // Consumer-1 failed mid-process: no lock release, no XACK.
+    // Consumer-2 reclaims the entry via XAUTOCLAIM and processes it.
+    const job = makeJob();
+    const entry = makeEntry(job, "2000-0");
+
+    await (consumer2 as never as { _processEntry: (e: typeof entry) => Promise<void> })._processEntry(entry);
+
+    // Consumer-2 spawned exactly one container.
+    expect(spawner2.spawnCalls).toHaveLength(1);
+    expect(spawner2.spawnCalls[0].handle).toBe(job.handle);
+    expect(redis2.xAckCalls).toHaveLength(1);
+  });
+
+  it("two consumers race on the same reclaimed entry: exactly one spawns", async () => {
+    // Consumer-1 wins the spawn lock; consumer-2 loses.
+    const redis1 = makeFakeRedis({ setResultFn: () => "OK" });
+    const redis2 = makeFakeRedis({ setResultFn: () => null }); // null → lock held
+
+    const spawner1 = makeFakeSpawner();
+    const spawner2 = makeFakeSpawner();
+
+    const c1 = new DispatchStreamConsumer({
+      redis: redis1 as never,
+      spawner: spawner1,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+    const c2 = new DispatchStreamConsumer({
+      redis: redis2 as never,
+      spawner: spawner2,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+
+    vi.spyOn(c1, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+    vi.spyOn(c2, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    const job = makeJob();
+    const entry = makeEntry(job, "2100-0");
+
+    type PE = { _processEntry: (e: typeof entry) => Promise<void> };
+    await Promise.all([
+      (c1 as never as PE)._processEntry(entry),
+      (c2 as never as PE)._processEntry(entry),
+    ]);
+
+    const totalSpawns = spawner1.spawnCalls.length + spawner2.spawnCalls.length;
+    expect(totalSpawns).toBe(1);
+
+    // The lock loser (c2) XACKed to remove from its PEL without spawning.
+    expect(redis2.xAckCalls).toHaveLength(1);
+    expect(spawner2.spawnCalls).toHaveLength(0);
+  });
+});
+
+// ── C. M:N reconciler re-enqueue + slow spawn → spawn lock → one container ──
+
+describe("C. Reconciler re-enqueue racing a slow spawn (M:N dispatchers) — spawn lock", () => {
+  it("slow spawn + second entry for same handle: only one container spawned", async () => {
+    // Dispatcher-1 processes the original entry with a deliberate spawn delay.
+    // Dispatcher-2 processes a second entry (from the reconciler re-enqueue)
+    // for the same handle while dispatcher-1 is still mid-spawn.
+    // The spawn lock ensures only dispatcher-1 spawns.
+
+    // Dispatcher-1 wins the lock (slow spawn).
+    const redis1 = makeFakeRedis({ setResultFn: () => "OK" });
+    // Dispatcher-2 sees the lock as held.
+    const redis2 = makeFakeRedis({ setResultFn: () => null });
+
+    const spawner1 = makeFakeSpawner({ spawnDelayMs: 50 }); // induced slow spawn
+    const spawner2 = makeFakeSpawner();
+
+    const c1 = new DispatchStreamConsumer({
+      redis: redis1 as never,
+      spawner: spawner1,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+    const c2 = new DispatchStreamConsumer({
+      redis: redis2 as never,
+      spawner: spawner2,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+    });
+
+    vi.spyOn(c1, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+    vi.spyOn(c2, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    // Same handle — both entries refer to the same task execution.
+    const job = makeJob();
+    const entry1 = makeEntry(job, "3000-0"); // original dispatch
+    const entry2 = makeEntry(job, "3001-0"); // reconciler re-enqueue
+
+    type PE = { _processEntry: (e: { id: string; message: Record<string, string> }) => Promise<void> };
+
+    // Dispatcher-1 (slow): processes original entry.
+    // Dispatcher-2 (fast): processes re-enqueued entry concurrently.
+    await Promise.all([
+      (c1 as never as PE)._processEntry(entry1),
+      (c2 as never as PE)._processEntry(entry2),
+    ]);
+
+    // Exactly one container spawned (dispatcher-1 won the lock).
+    const totalSpawns = spawner1.spawnCalls.length + spawner2.spawnCalls.length;
+    expect(totalSpawns).toBe(1);
+
+    // Dispatcher-2 (lock loser) XACKed to remove its entry from PEL.
+    expect(redis2.xAckCalls).toHaveLength(1);
+    expect(spawner2.spawnCalls).toHaveLength(0);
+  });
+});
+
+// ── D. DLQ routing → synthetic failed completion at callback_url ─────────────
+
+describe("D. DLQ routing — synthetic failed completion reaches broker callback", () => {
+  it("job exceeding maxDeliveries: DLQ write + synthetic /callback with terminal_status=failed", async () => {
+    const entryId = "4000-0";
+    // maxDeliveries=3; pending shows 4 deliveries → exceeds limit.
+    const pendingByEntryId = new Map([[entryId, 4]]);
+
+    const redis = makeFakeRedis({ pendingByEntryId });
+    const spawner = makeFakeSpawner();
+
+    const postedBodies: string[] = [];
+    vi.mocked(nodeHttp.request).mockImplementation(
+      (_opts: unknown, cb?: (res: { resume: () => void }) => void) => {
+        const chunks: string[] = [];
+        const req: {
+          on: () => unknown;
+          write: (c: string) => void;
+          end: () => void;
+        } = {
+          on: vi.fn().mockReturnThis(),
+          write: vi.fn((chunk: string) => { chunks.push(chunk); }),
+          end: vi.fn(() => {
+            postedBodies.push(chunks.join(""));
+            cb?.({ resume: vi.fn() });
+          }),
+        };
+        return req as never;
+      },
+    );
+
+    const consumer = new DispatchStreamConsumer({
+      redis: redis as never,
+      spawner,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+      maxDeliveries: 3,
+    });
+    vi.spyOn(consumer, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    const job = makeJob({ callback_url: "http://broker:7000/callback" });
+    const entry = makeEntry(job, entryId);
+    await (consumer as never as { _processEntry: (e: typeof entry) => Promise<void> })._processEntry(entry);
+
+    // DLQ must have received the entry.
+    const dlqWrites = redis.xAddCalls.filter((c) => c.key === DISPATCH_DLQ_KEY);
+    expect(dlqWrites).toHaveLength(1);
+
+    // Synthetic callback must have been posted.
+    expect(postedBodies).toHaveLength(1);
+    const body = JSON.parse(postedBodies[0]) as {
+      handle: string;
+      nonce: string;
+      result: { terminal_status: string };
+    };
+    expect(body.handle).toBe(job.handle);
+    expect(body.nonce).toBe(job.nonce);
+    expect(body.result.terminal_status).toBe("failed");
+
+    // Entry must have been XACK'd (no further redeliveries).
+    expect(redis.xAckCalls.some((c) => c.id === entryId)).toBe(true);
+
+    // Spawner must NOT have been called.
+    expect(spawner.spawnCalls).toHaveLength(0);
+
+    vi.mocked(nodeHttp.request).mockReset();
+  });
+});
+
+// ── E. Concurrent coexistence isolation ──────────────────────────────────────
+
+describe("E. Concurrent coexistence — bundled ∥ standalone isolation", () => {
+  it("two dispatchers for different handles use independent spawn locks (no key collision)", async () => {
+    const redisA = makeFakeRedis();
+    const redisB = makeFakeRedis();
+    const spawnerA = makeFakeSpawner();
+    const spawnerB = makeFakeSpawner();
+
+    const cA = new DispatchStreamConsumer({
+      redis: redisA as never,
+      spawner: spawnerA,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+      consumerId: "dispatcher-a",
+    });
+    const cB = new DispatchStreamConsumer({
+      redis: redisB as never,
+      spawner: spawnerB,
+      credential: makeFakeCredential(),
+      ...BASE_OPTS,
+      consumerId: "dispatcher-b",
+    });
+
+    vi.spyOn(cA, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+    vi.spyOn(cB, "_getRegistrySize" as never).mockResolvedValue(0 as never);
+
+    const jobA = makeJob();
+    const jobB = makeJob();
+    // Different handles → different lock keys → no interference.
+    expect(jobA.handle).not.toBe(jobB.handle);
+
+    const entryA = makeEntry(jobA, "5000-0");
+    const entryB = makeEntry(jobB, "5001-0");
+
+    type PE = { _processEntry: (e: { id: string; message: Record<string, string> }) => Promise<void> };
+    await Promise.all([
+      (cA as never as PE)._processEntry(entryA),
+      (cB as never as PE)._processEntry(entryB),
+    ]);
+
+    // Both dispatchers spawned their respective containers.
+    expect(spawnerA.spawnCalls).toHaveLength(1);
+    expect(spawnerA.spawnCalls[0].handle).toBe(jobA.handle);
+
+    expect(spawnerB.spawnCalls).toHaveLength(1);
+    expect(spawnerB.spawnCalls[0].handle).toBe(jobB.handle);
+
+    // Lock keys are handle-scoped — the two sets of lock keys must not overlap.
+    const lockKeysA = redisA.setCalls.map((c) => c.key);
+    const lockKeysB = redisB.setCalls.map((c) => c.key);
+
+    const lockKeySetA = new Set(lockKeysA);
+    const lockKeySetB = new Set(lockKeysB);
+
+    // No key from A appears in B's set (different handle → different lock key).
+    for (const k of lockKeySetA) {
+      expect(lockKeySetB.has(k)).toBe(false);
+    }
+  });
+
+  it("executor_workdir is handle-scoped (no workspace collision between two tasks)", () => {
+    // Workspace dirs are exec-<handle> — UUID handles guarantee uniqueness.
+    const h1 = randomUUID();
+    const h2 = randomUUID();
+    expect(h1).not.toBe(h2);

